import { clients } from "./clients";
import { orders } from "./operations";
import { points } from "./points";

/**
 * Synthetic CMR photos for the demo (generated by scripts/generate-cmr.ts into
 * public/cmr-samples). Every sample carries its ground truth, so it doubles as
 * the AI control set. All data is fictional.
 */

export type CmrVariant = "ostry" | "rozmazany" | "bez-pieczatki" | "uwagi" | "krzywy" | "obcy";

export type CmrTruth = {
  cmrNumber: string;
  sender: string;
  senderAddress: string;
  consignee: string;
  consigneeAddress: string;
  placeOfDelivery: string;
  deliveryCity: string;
  takeoverPlace: string;
  issuedDate: string;
  goods: string;
  packages: number;
  weightKg: number;
  references: string[];
  carrier: string;
  stamp: boolean;
  signature: boolean;
  remarks: string | null;
  legible: boolean;
};

export type CmrSample = {
  id: string;
  orderId: string | null;
  orderNumber: string | null;
  variant: CmrVariant;
  file: string;
  label: string;
  truth: CmrTruth;
};

export const CARRIER = "TransDemo Sp. z o.o., ul. Transportowa 12, 62-052 Komorniki (fikcyjny przewoźnik demo)";

const GOODS: Record<string, string> = {
  "cl-meble": "Meble tapicerowane, zapakowane w folię",
  "cl-baltic": "Żywność chłodzona +2…+6 °C",
  "cl-odra": "Środki chemiczne UN 1993, kl. 3",
  "cl-agropol": "Pasza w workach 25 kg",
  "cl-wisla": "Drobnica paletowa",
  "cl-sudety": "Papier w rolach",
  "cl-mazovia": "Elektronika użytkowa",
  "cl-hanza": "Artykuły gospodarstwa domowego",
};

const VARIANT_LABEL: Record<CmrVariant, string> = {
  ostry: "ostre zdjęcie",
  rozmazany: "rozmazane zdjęcie",
  "bez-pieczatki": "bez pieczątki odbiorcy",
  uwagi: "z adnotacją o szkodzie",
  krzywy: "krzywo, z cieniem",
  obcy: "CMR obcego zlecenia",
};

function truthFor(orderId: string, variant: CmrVariant, index: number): CmrTruth {
  const o = orders.find((x) => x.id === orderId)!;
  const client = clients.find((c) => c.id === o.clientId)!;
  const pickup = points.find((p) => p.id === o.pickupPointId)!;
  const delivery = points.find((p) => p.id === o.deliveryPointId)!;
  return {
    cmrNumber: `PL ${String(4471200 + index * 37).padStart(7, "0")}`,
    sender: client.name,
    senderAddress: `${pickup.address}, ${pickup.city} (${pickup.country})`,
    consignee: delivery.name,
    consigneeAddress: `${delivery.address}, ${delivery.city} (${delivery.country})`,
    placeOfDelivery: `${delivery.city}, ${delivery.country}`,
    deliveryCity: delivery.city,
    takeoverPlace: `${pickup.city}, ${pickup.country}`,
    issuedDate: "09.10.2026",
    goods: GOODS[o.clientId] ?? "Ładunek drobnicowy",
    packages: o.cargoPallets,
    weightKg: o.cargoKg,
    references: o.references,
    carrier: CARRIER,
    stamp: variant !== "bez-pieczatki",
    signature: variant !== "bez-pieczatki",
    remarks: variant === "uwagi" ? "2 palety uszkodzone, folia rozerwana — przyjęto z zastrzeżeniem" : null,
    legible: variant !== "rozmazany",
  };
}

const PLAN: [string, CmrVariant][] = [
  ["zl-1031", "ostry"],
  ["zl-1031", "bez-pieczatki"],
  ["zl-1032", "ostry"],
  ["zl-1033", "ostry"],
  ["zl-1034", "ostry"],
  ["zl-1034", "rozmazany"],
  ["zl-1035", "ostry"],
  ["zl-1035", "uwagi"],
  ["zl-1036", "ostry"],
  ["zl-1037", "ostry"],
  ["zl-1038", "ostry"],
  ["zl-1038", "rozmazany"],
  ["zl-1039", "ostry"],
  ["zl-1040", "ostry"],
  ["zl-1040", "krzywy"],
  ["zl-1041", "ostry"],
];

export const cmrSamples: CmrSample[] = [
  ...PLAN.map(([orderId, variant], i) => {
    const number = orders.find((o) => o.id === orderId)!.number;
    return {
      id: `${number.toLowerCase()}-${variant}`,
      orderId,
      orderNumber: number,
      variant,
      file: `/cmr-samples/${number.toLowerCase()}-${variant}.jpg`,
      label: `${number} · ${VARIANT_LABEL[variant]}`,
      truth: truthFor(orderId, variant, i),
    };
  }),
  {
    id: "obcy-1",
    orderId: null,
    orderNumber: null,
    variant: "obcy",
    file: "/cmr-samples/obcy-1.jpg",
    label: VARIANT_LABEL.obcy,
    truth: {
      cmrNumber: "DE 0098812",
      sender: "Nordhafen Logistik GmbH",
      senderAddress: "Hafenstraße 4, Rostock (DE)",
      consignee: "Kowalski Budownictwo s.c.",
      consigneeAddress: "ul. Zielona 8, Kalisz (PL)",
      placeOfDelivery: "Kalisz, PL",
      deliveryCity: "Kalisz",
      takeoverPlace: "Rostock, DE",
      issuedDate: "08.10.2026",
      goods: "Materiały budowlane",
      packages: 18,
      weightKg: 16200,
      references: ["NH-77120"],
      carrier: "Ostsee Trans GmbH, Rostock",
      stamp: true,
      signature: true,
      remarks: null,
      legible: true,
    },
  },
];

export function cmrSample(id: string): CmrSample | undefined {
  return cmrSamples.find((s) => s.id === id);
}

export function samplesForOrder(orderId: string): CmrSample[] {
  return cmrSamples.filter((s) => s.orderId === orderId);
}
